import{_ as a}from"./chunks/7f48b888566f114b3633.Cs5GVtc8.js";import{_ as i,C as r,o as s,c as o,j as t,a as n,E as l,a5 as c}from"./chunks/framework.DNkHA0lr.js";const q=JSON.parse('{"title":"这3个决定将决定你是否能致富","description":"","frontmatter":{"title":"这3个决定将决定你是否能致富","originalTitle":"These 3 Decisions Will Determine If You Get Rich","date":"2025-07-10","originalUrl":"https://thedankoe.com/letters/these-3-decisions-will-determine-if-you-get-rich/","minutes":8,"sourceHash":"9a706d65108dcfd0048b1f9f29efd1bdd669b5711b608f3d2b33e3271f7d737a","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/these-3-decisions-will-determine-if-you-get-rich/"}]]},"headers":[],"relativePath":"letters/these-3-decisions-will-determine-if-you-get-rich.md","filePath":"letters/these-3-decisions-will-determine-if-you-get-rich.md"}'),m={name:"letters/these-3-decisions-will-determine-if-you-get-rich.md"};function d(h,e,f,_,u,b){const p=r("ArticleMeta");return s(),o("div",null,[e[0]||(e[0]=t("h1",{id:"这3个决定将决定你是否能致富",tabindex:"-1"},[n("这3个决定将决定你是否能致富 "),t("a",{class:"header-anchor",href:"#这3个决定将决定你是否能致富","aria-label":'Permalink to "这3个决定将决定你是否能致富"'},"​")],-1)),l(p),e[1]||(e[1]=c('<p>致富的唯一途径是（1）以一种妄想般的美元数额来衡量你时间的价值，（2）对致富极度痴迷，以及（3）除了致富，不给自己留任何退路。</p><p>现在，我知道后面会有几个人在尖叫“金钱不是一切！”或者反刍着一句肤浅的“金钱买不到快乐”，这句肤浅的话是他们从某个既不懂金钱也不懂快乐的人那里听来的。但这封信是写给那些点进来不是为了生气并彻底浪费自己时间的人的。</p><p>这封信是写给那些想要理直气壮地致富的人的。</p><p>不是因为你是个糟糕邪恶的人，而是因为在你脑海中，唯一的另一个选择就是让市场来决定你的价值，而这太可怕了。</p><p>就我个人而言，我很早就意识到，我<em>绝对无法</em>接受每天拼死拼活工作8到10个小时，只为了在一份我一无所有、做着我毫不关心的工作里每年赚8到15万美元，<em>尤其是</em>当我非常清楚地看到，有些人做着有意义的工作，工作时间只有我的一小部分，收入却是我的100倍时。</p><p>显然，我年轻时可能还没有创造那么多收入的价值，但我知道那是可能的。</p><p>我知道我可以做出一系列决定，从而让我对金钱拥有极大的掌控权，使它不再主宰我的头脑、情绪或时间。那些无休止地对金钱进行道德绑架和精神升华的人，根本无法想象一种不被金钱束缚的生活。</p><p>虽然我不能确切地告诉你该怎么做（我的意思是，我可以告诉你，但现实的结果因人而异），但我<em>确实可以</em>给你3个重塑大脑的方法，让你达到能够<em>做出导致你致富的正确决定</em>的程度。</p><p>换句话说，我可以在你脑海中植入这些信念，帮助你测试那些更有可能让现实最终吐出财富作为结果的输入。</p><h3 id="理想的时薪" tabindex="-1">理想的时薪 <a class="header-anchor" href="#理想的时薪" aria-label="Permalink to &quot;理想的时薪&quot;">​</a></h3><blockquote><p>设定并强制执行一个理想的时薪。如果解决一个问题省下的钱低于你的时薪，那就忽略它。如果外包一项任务的花费低于你的时薪，那就外包它……我的理想时薪是5000美元/小时。</p><p>—— 纳瓦尔·拉维坎特 (Naval Ravikant)</p></blockquote><p>这会让大多数人感到困惑（它肯定也会让过去的我感到困惑），但我现在已经到了这样的地步：有人可能出价5000美元跟我进行一对一的通话，而我也不会答应。不是因为我不需要这笔钱，或者我不想帮助别人，而是因为这涉及到时间、注意力，以及必须提供价值5000美元的回报的义务。这是一项重大的责任，要求我必须将其置于其他具有更大潜在回报的事情之上。</p><p>当我清楚地知道该怎么做才能在一小时内赚到比这更多的钱时，再去分散我的注意力那就太愚蠢了。</p><p>设定理想时薪的目的正在于此：做出更好的决定，并调整你的思维框架，去注意到那些能让你处于更高杠杆位置的机会。</p><p>让我们想象一下，你买了一件50美元有缺陷或坏掉的物品。你会愿意花一个小时的麻烦去退货吗？如果会，说明你认为你的时间价值是每小时50美元，甚至更低。这并不是一件“坏”事，但它把意识的光芒照在了一个更重要的事实上：你并没有意识到，在同一个小时里，你可以去解决一个能让你赚到500美元——甚至5000美元——的问题。如果你意识到了，花那一个小时去退货就没有任何意义了。</p><p>如果你的理想时薪让你觉得并非遥不可及，那它就太低了。</p><p>为什么？</p><p>妄想般的目标会重塑你的大脑。</p><p>根据你所学习和思考的内容（包括这封信），你的大脑此刻正在实质性地自我重塑。当你想象一个更美好的未来时，它会激活与你正在经历这些事时相同的大脑网络。每一个全神贯注的瞬间，都是一个重塑大脑以契合你想成为的那种人的机会。这就是为什么那些不断刷负面新闻的人，以及那些不管理自己输入（精神上的或物质上的）的人，正在一分一秒地自掘坟墓的众多原因之一。</p><p>除此之外，多巴胺在追求目标的过程中比在实现目标时分泌得更多。但这正是危险所在。整天将目标可视化确实能增强学习效果，但这必须与来自现实世界场景中恰到好处的挑战水平相结合才行。也就是要真正入局。否则，这就变成了精神手淫：把你的目标告诉所有人，以此获得廉价的多巴胺刺激，却从来不采取任何实际行动。</p><p><a href="https://substackcdn.com/image/fetch/$s_!BjQ4!,f_auto,q_auto:good,fl_progressive:steep/https%3A%2F%2Fsubstack-post-media.s3.amazonaws.com%2Fpublic%2Fimages%2F00a1e63e-a54e-4533-9a28-9d74d511c32d_1000x1000.png" target="_blank" rel="noreferrer"><img src="'+a+'" alt=""></a></p><p>挑战的黄金区间大约是85%的难度。不会高到让你焦虑，也不会低到让你觉得无聊。挑战逐渐超负荷所带来的压力会释放去甲肾上腺素，这会进一步增强学习效果，并帮助你适应那种新的心理状态。</p><p>所以，你不能只是想想你的理想时薪，然后祈祷自己能赚更多的钱。</p><p>你需要<em>牢记</em>你的时薪来做出艰难的决定。</p><p>就从不去退那件物品开始吧。</p><p>你会没事的。</p><h3 id="集中力量是致富的唯一途径" tabindex="-1">集中力量是致富的唯一途径 <a class="header-anchor" href="#集中力量是致富的唯一途径" aria-label="Permalink to &quot;集中力量是致富的唯一途径&quot;">​</a></h3><p>如果你想致富，它必须成为你压倒一切的头号渴望。</p><p>至少要一直持续到致富的行动已经深深烙印在你的心灵中，以至于你不需要耗费太多心力就能去执行它们，就像职业篮球运动员不需要去<em>思考</em>如何在关键时刻投进三分球一样。</p><p>这对任何你想获得成功的事情都适用：集中力量是成为实现大目标的人的唯一途径。你需要痴迷。你需要把尽可能多的能量投入到那个目标中。</p><p>但是出去玩呢？享受生活呢？社交呢？追求西方定义的幸福（一种根本不可能持续的狂喜状态）呢？</p><p>那么，你将不会创造财富，因为那不是你的<em>首要任务</em>。这完全没有问题。你并不<em>需要</em>有致富的目标，但很多人有，而且他们和你一样对生命的意义有着错误的认知，一个不把致富作为首要任务的人是不会偶然发财的。作为一个附带目标，在接下来的40年里把几块钱投资到股票市场，确实是在晚年享受一笔可观财富的一种方式，但是如果有人具备相关的知识，哪个心智正常的人会不想提早30年得到这笔钱甚至更多呢？</p><p>哦，顺便说一句，把致富作为首要任务并不会让生活变得更糟，它会让生活变得好得不可思议。</p><p>职业运动员的生活很糟糕吗？可能不是，大多数时候他们都在做自己热爱的事情。那么，为什么你不把同样的逻辑应用到商业上呢？一个人难道不能在尝试于自己选择的领域内发挥出巅峰水平的同时，拥有美好的生活吗？</p><p>有人可能会说，幸福是取得进步和为比自己更伟大的事物做出贡献的结合，因此，当你没有从这种进步中分心，并且在规模化地解决有价值的问题时（这也就是创业的本质），生活要比普通人享受一千倍。</p><p>是的，你仍然必须做生活需要你做的事情，但这样做会让你感到痛苦。这种痛苦就是你指导决策的方式。因为你越是容忍它，你就越不会采取行动去改变它。</p><p>为了让这一点变得切实可行，从创建一份你<em>不做</em>的事情清单开始吧。</p><p>那些根本不值得你花时间的事情。咖啡会议。退掉愚蠢的物品。因为无聊而刷手机。因为缺乏热情和适当的刺激而去聚会。按时回复所有人的短信（这尤其愚蠢，因为没有任何人的大脑结构能够适应别人随时来获取自己的注意力）。那些可以外包或忽略的琐碎待办事项。当面临这些决定时，坚定地说：“我不做那件事。”</p><p>然后，创建一份你<em>会做</em>的事情清单。</p><p>那些将你真实时薪与理想时薪结合起来的事情。学习能大幅提高你赚钱潜力的信息。练习让你能自力更生的技能。创办一家企业。加入一家初创公司。争取一个高管职位。学习和建设。</p><p>你越是反思自己的行为，就越容易看清为什么你还没富起来。</p><h3 id="别给自己留退路-只能成功" tabindex="-1">别给自己留退路，只能成功 <a class="header-anchor" href="#别给自己留退路-只能成功" aria-label="Permalink to &quot;别给自己留退路，只能成功&quot;">​</a></h3><p>我做过的最好的决定，总是涉及到把钱当作一种倒逼机制（forcing function）来赚更多的钱。</p><p>换句话说，我投资了我负担不起的东西，而且我学会了相信自己能更快地把钱赚回来。</p><p>我收入的第一次显著飙升发生在我花1500美元购买了一款电子邮件营销和产品托管软件之后。在那时，那笔钱对我来说非常宝贵。花那笔钱让我深深感到肉痛。当点击“购买”时，我感到了一阵强烈的焦虑。但那种痛苦驱使我拼命去把钱赚回来，就好像我的命全靠它一样。它强迫我去学习如何利用营销、文案和漏斗知识来最大化它的价值。有了那次购买，我不再需要去猜测该学习哪些“高价值”技能。很明显，只要我学会了它们，我就能增加我赚钱的潜力。</p><p>同样的事情发生在我不断搬进各种公寓时。一套比一套贵。每一套的花费都超过了让我感到舒服的金额。表面上看，似乎我只是生活方式膨胀的又一个受害者。实际上，这是在现实世界中，为我深知自己能应对的挑战设定一个最后期限的<em>现实方法</em>。我在物理层面上将自己置身于未来自我的环境中，我无法再退回到那种我不再想要的生活里。</p><p>那3个决定——理想的时薪、集中力量、以及别给自己留退路只能成功——创造了完美的条件，让我赚到的钱远远超出了年轻时的我认为可能赚到的数量。</p><p>这些决定中没有一个涉及到纠结“学什么技能”或“选择什么商业模式”。我根本没时间去想这些。我必须把它们<em>全</em>学了。</p><p>当然，这需要经历大量的失败和迭代，但这可是社交媒体，谁会谈论那些东西呢 ;）？虽然我不提倡一夜暴富，但如果你按照这封信中概述的那样设定了正确的条件，你会惊讶于自己致富的速度有多快。事实上，我敢说你能在两周内学会任何技能（并且比99%的人做得都好）。</p><p>我会把这个话题留到另一封信里讲。</p><p>感谢你阅读这封信。</p><p>—— 丹 (Dan)</p><p>如果你想学习让你为未来做好准备的技能，<a href="https://letters.thedankoe.com/" target="_blank" rel="noreferrer">考虑加入我Substack的付费订阅</a>。里面有一个技能库，包含各种AI提示词、写作策略、营销策略，以及一门完整的一人企业课程。致富的唯一途径是（1）以一种妄想般的美元数额来衡量你时间的价值，（2）对致富极度痴迷，以及（3）除了致富，不给自己留任何退路。</p><hr><p><a href="/en/letters/these-3-decisions-will-determine-if-you-get-rich">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',55))])}const x=i(m,[["render",d]]);export{q as __pageData,x as default};
